describe('Modal Scroll Lock', () => {
  beforeEach(() => {
    cy.visit('/modal-page');
  });

  it('should prevent page scrolling when modal is open', () => {
    // Verify page is visible and scrollable before modal opens
    cy.get('[data-testid="page-content"]').should('be.visible');
    cy.get('[data-testid="page-content"]').then(($content) => {
      const height = $content.height();
      const scrollHeight = $content[0].scrollHeight;
      expect(height).to.be.greaterThan(0);
      expect(scrollHeight).to.be.greaterThan(height);
    });

    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify page content is still visible behind modal
    cy.get('[data-testid="page-content"]').should('be.visible');

    // Attempt to scroll the page while modal is open
    cy.get('body').then(($body) => {
      const initialScrollTop = $body.scrollTop();
      cy.scrollTo('bottom');
      const finalScrollTop = $body.scrollTop();
      expect(finalScrollTop).to.equal(initialScrollTop);
    });

    // Verify modal is still open and scroll lock is active
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Close the modal
    cy.get('[data-testid="close-modal-button"]').click();
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });

  it('should allow page scrolling when modal is closed', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify page is scroll-locked
    cy.get('body').then(($body) => {
      const initialScrollTop = $body.scrollTop();
      cy.scrollTo('bottom');
      const finalScrollTop = $body.scrollTop();
      expect(finalScrollTop).to.equal(initialScrollTop);
    });

    // Close the modal
    cy.get('[data-testid="close-modal-button"]').click();
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify page is now scrollable
    cy.get('[data-testid="page-content"]').then(($content) => {
      const initialScrollTop = $content[0].scrollTop;
      cy.scrollTo('bottom');
      const finalScrollTop = $content[0].scrollTop;
      expect(finalScrollTop).to.be.greaterThan(initialScrollTop);
    });
  });
});
